SELECT CASE WHEN c.credit_limit >= 12800 THEN 'high' WHEN c.credit_limit >= 7400 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, c.segment, MIN(t.amount) AS min_amount, COUNT(CASE WHEN t.merchant = 'Starbucks' THEN 1 END) AS starbucks_count FROM transactions t LEFT OUTER JOIN accounts a ON a.id = t.account_id INNER JOIN customers c ON c.id = a.customer_id WHERE c.city = 'London' GROUP BY CASE WHEN c.credit_limit >= 12800 THEN 'high' WHEN c.credit_limit >= 7400 THEN 'mid' ELSE 'low' END, c.segment ORDER BY 3
